self.console = {
  log: (...args) => self.postMessage({ type: "log", message: args }),
  error: (...args) => self.postMessage({ type: "error", message: args }),
  warn: (...args) => self.postMessage({ type: "warn", message: args })
};
self.onmessage = (event) => {
  const { code, canvas } = event.data;
  if (code && canvas) {
    self.document = {
      createElement: (type) => {
        if (type === "canvas") return canvas;
        return null;
      },
      body: {
        // Some libraries check for document.body
        appendChild: (el) => {
        }
      }
    };
    self.window = self;
    try {
      new Function(code)();
    } catch (error) {
      self.console.error("Execution Error:", error.message);
    }
  } else if (code) {
    try {
      new Function(code)();
    } catch (error) {
      self.console.error("Execution Error:", error.message);
    }
  }
};
